insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_tech_v1'
from (values
('126.17.c.1.A',3,'A student uses a concept map to break a big school-fundraiser problem into smaller tasks. This is called...','["decomposition", "debugging", "encryption", "compression"]'::jsonb,0,'Decomposition splits a problem into smaller parts.','original'),
('126.17.c.1.A',3,'Which tool shows a problem broken into branches and sub-branches?','["a password manager", "a mind map", "a spreadsheet formula", "a screenshot"]'::jsonb,1,'Visual maps show how parts connect.','original'),
('126.17.c.1.B',3,'In a learning map, a repeating arrangement of steps is a...','["virus", "cookie", "pattern", "firewall"]'::jsonb,2,'Patterns repeat in a predictable way.','original'),
('126.17.c.1.B',3,'Looking at a diagram to see which step must come before another helps analyze its...','["battery life", "file size", "resolution", "sequence"]'::jsonb,3,'Sequence is the order of steps.','original'),
('126.17.c.1.C',3,'Abstraction means...','["focusing on the important details and ignoring the rest", "copying a file", "adding every possible detail", "deleting all information"]'::jsonb,0,'Abstraction simplifies by hiding unneeded detail.','original'),
('126.17.c.1.C',3,'Which is a generalized description rather than a specific one?','["my neighbor''s blue truck", "any vehicle with wheels", "a red 2019 sedan with license 123", "the bus that stops at 7:14"]'::jsonb,1,'General terms cover many cases.','original'),
('126.17.c.1.D',3,'A team plans a project using a flowchart-style diagram so they can...','["skip planning", "hide the problem", "document the problem, possible solutions and steps", "delete the solution"]'::jsonb,2,'Visual plans help teams agree on steps.','original'),
('126.17.c.1.D',3,'A shared planning board for a group project lets teammates...','["work in secret", "avoid talking", "erase each other''s work", "see tasks and update progress together"]'::jsonb,3,'Collaboration needs shared visibility.','original'),
('126.17.c.1.E',3,'Debugging a program means...','["finding and fixing errors", "deleting the program", "adding more errors", "making the screen brighter"]'::jsonb,0,'Bugs are mistakes in code or logic.','original'),
('126.17.c.1.E',3,'A useful debugging technique is to...','["run it blindly", "test the code one small step at a time", "rewrite everything at once", "ignore error messages"]'::jsonb,1,'Small tests isolate where the problem is.','original'),
('126.17.c.1.F',3,'Iteration in an algorithm means...','["deleting steps", "running once only", "repeating a set of steps", "pausing forever"]'::jsonb,2,'Iteration is repetition.','original'),
('126.17.c.1.F',3,'A benefit of using a loop is that it...','["hides errors", "makes code longer", "stops the program", "saves time by not writing the same steps over and over"]'::jsonb,3,'Loops reduce repetition.','original'),
('126.17.c.2.A',3,'A variable is a named place that...','["stores a value a program can use or change", "blocks pop-ups", "prints paper", "connects to Wi-Fi"]'::jsonb,0,'Variables hold data.','original'),
('126.17.c.2.A',3,'Which is the best name for a variable that holds a player''s points?','["x1x1", "score", "thing", "abc"]'::jsonb,1,'Descriptive names make code easier to read.','original'),
('126.17.c.2.B',3,'A sequence in a program is...','["a kind of file", "steps that run at random", "steps that run in order", "a type of virus"]'::jsonb,2,'Order matters in sequences.','original'),
('126.17.c.2.B',3,'A design process for programming usually starts by...','["testing a finished app", "uploading the code", "choosing a font", "defining the problem you want to solve"]'::jsonb,3,'Planning comes first.','original'),
('126.17.c.3.A',3,'A student stuck on a design step uses goal setting by...','["breaking the goal into smaller targets and trying again", "giving up", "waiting for someone else", "blaming a teammate"]'::jsonb,0,'Goals and persistence solve challenges.','original'),
('126.17.c.3.A',3,'A personal characteristic that helps solve a design problem is...','["carelessness", "perseverance", "impatience", "procrastination"]'::jsonb,1,'Staying with a challenge builds solutions.','original'),
('126.17.c.3.B',3,'A design process using digital tools can be used to...','["avoid choices", "skip testing", "compare and contrast different ideas before choosing one", "copy someone else''s work"]'::jsonb,2,'Digital tools help evaluate options.','original'),
('126.17.c.3.B',3,'Testing a prototype helps designers...','["avoid feedback", "stop designing", "hide flaws", "find what to improve"]'::jsonb,3,'Testing reveals needed changes.','original'),
('126.17.c.3.C',3,'A design process is used by architects, engineers and game designers to...','["plan, build and improve products", "avoid planning", "never revise", "skip testing"]'::jsonb,0,'Many industries follow similar steps.','original'),
('126.17.c.3.C',3,'Which job uses a design process?','["a person who only counts coins", "app developer", "a person who only sweeps floors", "a person who never plans"]'::jsonb,1,'Developers plan and refine apps.','original'),
('126.17.c.4.A',3,'Compared with a century ago, communication changed greatly because of...','["horses", "town criers only", "telephones, then the internet and smartphones", "carrier pigeons"]'::jsonb,2,'Technology changed how we connect.','original'),
('126.17.c.4.A',3,'The invention of the printing press mainly changed...','["how rain falls", "how plants grow", "how fast cars drive", "how quickly ideas and books could be shared"]'::jsonb,3,'It spread information widely.','original'),
('126.17.c.4.B',3,'A global trend such as remote work has affected technology by...','["increasing demand for video meetings and cloud tools", "banning computers", "ending the internet", "removing email"]'::jsonb,0,'Trends drive new tools.','original'),
('126.17.c.4.B',3,'Growing concern about climate change has led technology companies to develop...','["heavier phones", "energy-efficient devices", "paper-only systems", "fewer sensors"]'::jsonb,1,'Global needs shape inventions.','original'),
('126.17.c.4.C',3,'A student who learned to use one slideshow app and then quickly learns another is...','["starting from zero", "copying homework", "transferring knowledge to a new technology", "avoiding technology"]'::jsonb,2,'Skills carry over.','original'),
('126.17.c.4.C',3,'When you meet a new app, a good first step is to...','["ignore it", "guess blindly", "delete it", "look for familiar features and explore the menus"]'::jsonb,3,'Prior knowledge helps.','original'),
('126.17.c.5.A',3,'In a Boolean expression, the value of a true-or-false statement is...','["either true or false", "a picture", "a number from 1 to 10", "a color"]'::jsonb,0,'Boolean values are true/false.','original'),
('126.17.c.5.A',3,'A computer can store the answer to ''Is the door open?'' as...','["a sound", "a Boolean value", "an image", "a long paragraph"]'::jsonb,1,'True/false questions use Booleans.','original'),
('126.17.c.5.B',3,'Searching for ''pizza AND vegan'' will most likely return results that...','["are blank", "contain neither word", "contain both words", "contain only one word"]'::jsonb,2,'AND narrows results.','original'),
('126.17.c.5.B',3,'Putting quotation marks around a phrase in a search tells the engine to...','["delete the results", "search images only", "ignore the phrase", "look for that exact phrase"]'::jsonb,3,'Quotes require an exact match.','original'),
('126.17.c.6',3,'To sort a list of names alphabetically in a spreadsheet, you would use...','["the sort feature", "the print button", "the spell checker", "a screen saver"]'::jsonb,0,'Sorting organizes data.','original'),
('126.17.c.6',3,'A spreadsheet formula that adds a column of numbers is...','["SUNSET", "SUM", "SIZE", "COUNTRY"]'::jsonb,1,'SUM totals values.','original'),
('126.17.c.7',3,'To communicate survey results, a student could...','["erase the survey", "send only raw numbers", "make a chart and share it in a presentation", "hide the data"]'::jsonb,2,'Visuals communicate results.','original'),
('126.17.c.7',3,'Publishing results online responsibly means...','["posting passwords", "including everyone''s address", "sharing without checking", "removing private information before sharing"]'::jsonb,3,'Protect privacy.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_tech_v1'
from (values
('126.17.c.8.A',3,'A digital footprint is...','["the trail of information you leave online", "a type of file", "a shoe print", "a printer setting"]'::jsonb,0,'Posts and searches add to it.','original'),
('126.17.c.8.A',3,'Posting a mean comment adds to your digital footprint in a way that can be...','["erased instantly", "permanent and visible to others", "invisible", "private"]'::jsonb,1,'Footprints can last.','original'),
('126.17.c.8.B',3,'An informal digital communication would be...','["a letter to a principal", "a job application", "a text to a friend", "a formal report"]'::jsonb,2,'Informal messages are casual.','original'),
('126.17.c.8.B',3,'Good digital etiquette in a formal email includes...','["all caps", "no greeting", "slang only", "a clear subject line and polite greeting"]'::jsonb,3,'Formal tone shows respect.','original'),
('126.17.c.8.C',3,'A tool for collaborating on a shared document online lets teammates...','["edit the same file at the same time", "print only", "use separate files", "avoid chatting"]'::jsonb,0,'Real-time collaboration saves effort.','original'),
('126.17.c.8.C',3,'When recording a group video presentation, each member should...','["talk over each other", "have a clear role and speak at the planned time", "stay silent", "leave early"]'::jsonb,1,'Planning improves group work.','original'),
('126.17.c.9.A',3,'An acceptable use policy (AUP) is a document that...','["lists lunch menus", "grants free games", "explains the rules for using school technology", "removes passwords"]'::jsonb,2,'AUPs set safe, ethical use rules.','original'),
('126.17.c.9.A',3,'Under an AUP, students should not...','["ask for help", "save work to their folder", "use school email for assignments", "share passwords or access others'' accounts"]'::jsonb,3,'Respect privacy and security.','original'),
('126.17.c.9.B',3,'Intellectual property is...','["original work created by a person or company", "a free picture", "any website", "a type of hardware"]'::jsonb,0,'It covers writing, art, music and inventions.','original'),
('126.17.c.9.B',3,'Copyright law protects the creator by...','["making it free", "giving them rights to control how their work is used", "deleting the work", "letting anyone copy it"]'::jsonb,1,'Creators hold rights.','original'),
('126.17.c.9.C',3,'A citation for a website should include...','["the font size", "only the color", "the author, title and URL or access date", "a random number"]'::jsonb,2,'Citations help others find sources.','original'),
('126.17.c.9.C',3,'You cite sources to...','["hide your research", "change the topic", "make the paper shorter", "give credit and avoid plagiarism"]'::jsonb,3,'Credit shows honesty.','original'),
('126.17.c.9.D',3,'A post that uses a misleading headline to get clicks is an example of...','["information being exaggerated", "a citation", "a verified fact", "a password"]'::jsonb,0,'Clickbait distorts facts.','original'),
('126.17.c.9.D',3,'A good way to check an exaggerated claim is to...','["assume it is true", "compare it with several reliable sources", "share it right away", "ignore it"]'::jsonb,1,'Verification stops misinformation.','original'),
('126.17.c.10.A',3,'Phishing is when someone...','["fixes your computer", "cleans your screen", "sends a fake message to trick you into giving information", "backs up your files"]'::jsonb,2,'Phishing steals data.','original'),
('126.17.c.10.A',3,'Malware is software designed to...','["improve battery life", "back up photos", "speed up Wi-Fi", "damage or steal from a device"]'::jsonb,3,'Malware is malicious software.','original'),
('126.17.c.10.B',3,'Impersonation in cyberbullying is when someone...','["pretends to be another person online to hurt them", "likes a post", "joins a class", "posts a recipe"]'::jsonb,0,'Impersonation is a form of harassment.','original'),
('126.17.c.10.B',3,'Cyberstalking involves...','["sharing a link to a game", "repeated unwanted online contact that makes someone afraid", "a single friendly message", "a class chat"]'::jsonb,1,'It is harassment.','original'),
('126.17.c.11',3,'To pick the best tool for a poster, a student should consider...','["the oldest device", "the loudest keyboard", "which software best fits the task and audience", "the biggest folder"]'::jsonb,2,'Match tools to needs.','original'),
('126.17.c.11',3,'A process for choosing technology includes...','["picking randomly", "never testing", "using only one tool forever", "identifying the goal, comparing options and testing"]'::jsonb,3,'Evaluation leads to better choices.','original'),
('126.17.c.12.A',3,'A cloud application is software that...','["runs over the internet and stores work online", "is a hardware part", "only runs without Wi-Fi", "is printed on paper"]'::jsonb,0,'Cloud apps are accessed through the web.','original'),
('126.17.c.12.A',3,'A keyboard is an example of an...','["storage device", "input device", "output device", "power supply"]'::jsonb,1,'Input devices send data to the computer.','original'),
('126.17.c.12.B',3,'A good file name for a science report is...','["asdf", "stuff", "Science_Report_Plants_2026", "new"]'::jsonb,2,'Clear names help organize files.','original'),
('126.17.c.12.B',3,'Putting files in folders by subject helps with...','["slowing the computer", "hiding passwords", "deleting them", "finding them later"]'::jsonb,3,'Folders organize files.','original'),
('126.17.c.12.C',3,'To make a bar graph from data, the best tool is likely...','["a spreadsheet", "a flashlight", "a game", "a calculator app"]'::jsonb,0,'Spreadsheets create charts.','original'),
('126.17.c.12.C',3,'To record a short narrated video, a student would choose...','["a spell checker", "a screen or video recorder", "a file manager", "a graph tool"]'::jsonb,1,'Pick a tool that fits the task.','original'),
('126.17.c.12.D',3,'Typing speed is commonly measured in...','["letters per hour", "keys per week", "words per minute", "pages per day"]'::jsonb,2,'WPM measures speed.','original'),
('126.17.c.12.D',3,'Improving typing accuracy means making fewer...','["pages", "words", "keys", "errors"]'::jsonb,3,'Accuracy is correctness.','original'),
('126.17.c.12.E',3,'The shortcut Ctrl+C (or Command+C) is used to...','["copy", "undo", "cut", "save"]'::jsonb,0,'C stands for copy.','original'),
('126.17.c.12.E',3,'The shortcut Ctrl+Z (or Command+Z) will usually...','["open a new tab", "undo the last action", "close the program", "print"]'::jsonb,1,'Undo reverses the last step.','original'),
('126.17.c.12.F',3,'If you can''t figure out how to make a table in a document, you can...','["turn off the device", "delete the file", "use the application''s help menu", "give up"]'::jsonb,2,'Help sources answer questions.','original'),
('126.17.c.12.F',3,'A good way to solve a software issue is to...','["keep clicking randomly", "uninstall everything", "ignore it", "search the help documentation or ask a teacher"]'::jsonb,3,'Research solves problems.','original'),
('126.17.c.12.G',3,'An example of remote data storage is...','["a cloud drive", "a monitor", "a USB port", "a mouse"]'::jsonb,0,'Cloud storage is off-device.','original'),
('126.17.c.12.G',3,'Local storage means data is saved on...','["a distant server only", "your own device", "a different planet", "the internet only"]'::jsonb,1,'Local = on your hardware.','original'),
('126.17.c.12.H',3,'A word processor is best for...','["running games", "building databases", "writing and formatting documents", "editing music"]'::jsonb,2,'Word processors create text documents.','original'),
('126.17.c.12.H',3,'Which tool is best for creating a brochure?','["a calculator", "a file zipper", "a stopwatch", "publication software"]'::jsonb,3,'Publication tools handle layout.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
